INSERT INTO public.rotas (id, slug, origem, destino, ida_e_volta, duracao, distancia, preco_pequeno, preco_grande, preco_pequeno_noite, preco_grande_noite, destaque, popularidade, resumo, descricao, embarque, foto, galeria, ativo, created_at, updated_at) VALUES
  ('49687f1b-d7d4-4cb9-be75-9a20af6827fa', 'barreirinhas-barra-grande', 'Barreirinhas', 'Barra Grande', false, '≈ 6h', '390 km', 950, NULL, NULL, NULL, NULL, 52, 'Das dunas direto para o point de kitesurf do litoral piauiense.', 'Transfer particular de Barreirinhas até Barra Grande (PI), destino de kite e vento constante. Espaço para equipamentos combinado na reserva. Saída no horário que você preferir.', ARRAY['Pousadas e hotéis em Barreirinhas','Pousadas em Barra Grande']::text[], '/frota/frota-8.jpeg', ARRAY['/frota/frota-8.jpeg','/frota/frota-7.jpeg','/frota/frota-5.jpeg']::text[], true, '2026-08-09T16:44:06.467072+00:00', '2026-08-09T16:44:06.467072+00:00'),
  ('5e65deb1-5d12-4f56-bba3-e03a1f7fad97', 'barreirinhas-jericoacoara', 'Barreirinhas', 'Jericoacoara', false, '≈ 9h', '600 km', 1600, NULL, NULL, NULL, 'Rota das Emoções', 66, 'A travessia completa dos Lençóis Maranhenses até as dunas de Jeri.', 'A perna mais longa da Rota das Emoções, feita em carro particular e com motorista que conhece cada trecho. Paradas programadas para almoço e descanso, e entrega em Jericoacoara conforme o acesso permitido no dia.', ARRAY['Pousadas e hotéis em Barreirinhas','Portaria de Jericoacoara / Jijoca']::text[], '/frota/frota-4.jpeg', ARRAY['/frota/frota-4.jpeg','/frota/frota-2.jpeg','/frota/frota-7.jpeg']::text[], true, '2026-08-09T16:44:06.467072+00:00', '2026-08-09T16:44:06.467072+00:00'),
  ('46832a97-14bf-4ba0-9028-7fe8ef5b54d3', 'barreirinhas-parnaiba', 'Barreirinhas', 'Parnaíba', false, '≈ 5h', '330 km', 850, NULL, NULL, NULL, NULL, 60, 'Conexão da rota das emoções em direção ao Delta do Parnaíba.', 'Trecho da Rota das Emoções entre Barreirinhas e Parnaíba, no Piauí. Viagem em carro particular, com paradas combinadas e horário de saída definido por você. Bagagem e prancha acomodadas conforme o veículo.', ARRAY['Pousadas e hotéis em Barreirinhas','Hotéis e aeroporto de Parnaíba']::text[], '/frota/frota-3.jpeg', ARRAY['/frota/frota-3.jpeg','/frota/frota-1.jpeg','/frota/frota-4.jpeg']::text[], true, '2026-08-09T16:44:06.467072+00:00', '2026-08-09T16:44:06.467072+00:00'),
  ('c68d44f1-59ee-4b32-949b-da717d84cc18', 'barreirinhas-santo-amaro', 'Barreirinhas', 'Santo Amaro', true, '≈ 2h', '110 km', 450, 550, NULL, NULL, NULL, 70, 'Ligação entre as duas bases dos Lençóis, sem depender de horário de van.', 'Ideal para quem quer conhecer os dois lados do parque na mesma viagem. Saída no horário que você escolher, direto da sua pousada em Barreirinhas até Santo Amaro (ou o contrário), com bagagem acomodada e ar-condicionado.', ARRAY['Pousadas e hotéis em Barreirinhas','Pousadas em Santo Amaro do Maranhão']::text[], '/frota/frota-6.jpeg', ARRAY['/frota/frota-6.jpeg','/frota/frota-3.jpeg','/frota/frota-8.jpeg']::text[], true, '2026-08-09T16:44:06.467072+00:00', '2026-08-09T16:44:06.467072+00:00'),
  ('f4f22b6f-93c4-4d50-ad7e-c0722609d11f', 'santo-amaro-barra-grande', 'Santo Amaro', 'Barra Grande', false, '≈ 7h', '440 km', 1200, NULL, NULL, NULL, NULL, 38, 'Do lado mais silencioso dos Lençóis até o vento de Barra Grande.', 'Viagem particular ligando Santo Amaro do Maranhão a Barra Grande, no Piauí. Ideal para quem está montando a Rota das Emoções sem depender de vans coletivas.', ARRAY['Pousadas em Santo Amaro do Maranhão','Pousadas em Barra Grande']::text[], '/frota/frota-2.jpeg', ARRAY['/frota/frota-2.jpeg','/frota/frota-8.jpeg','/frota/frota-4.jpeg']::text[], true, '2026-08-09T16:44:06.467072+00:00', '2026-08-09T16:44:06.467072+00:00'),
  ('5ca96c90-b9f0-405e-8e33-6f09ee1eec8a', 'santo-amaro-jericoacoara', 'Santo Amaro', 'Jericoacoara', false, '≈ 10h', '650 km', 1700, NULL, NULL, NULL, NULL, 40, 'Travessia longa de Santo Amaro até Jericoacoara em carro exclusivo.', 'Percurso completo entre Santo Amaro do Maranhão e Jericoacoara, com motorista dedicado, paradas para refeição e horário de saída combinado. Recomendamos sair no início da manhã.', ARRAY['Pousadas em Santo Amaro do Maranhão','Portaria de Jericoacoara / Jijoca']::text[], '/frota/frota-7.jpeg', ARRAY['/frota/frota-7.jpeg','/frota/frota-1.jpeg','/frota/frota-6.jpeg']::text[], true, '2026-08-09T16:44:06.467072+00:00', '2026-08-09T16:44:06.467072+00:00'),
  ('ae47d050-2dc6-4e13-a975-d3982e40bf4f', 'santo-amaro-parnaiba', 'Santo Amaro', 'Parnaíba', false, '≈ 6h', '380 km', 950, NULL, NULL, NULL, NULL, 44, 'Saída de Santo Amaro seguindo para o Delta do Parnaíba.', 'Transfer particular de Santo Amaro do Maranhão até Parnaíba, incluindo o trecho de areia até a estrada principal. Horário livre e acompanhamento do trajeto do começo ao fim.', ARRAY['Pousadas em Santo Amaro do Maranhão','Hotéis e aeroporto de Parnaíba']::text[], '/frota/frota-5.jpeg', ARRAY['/frota/frota-5.jpeg','/frota/frota-7.jpeg','/frota/frota-6.jpeg']::text[], true, '2026-08-09T16:44:06.467072+00:00', '2026-08-09T16:44:06.467072+00:00'),
  ('5968f178-d1b6-4dc1-9d20-3a39aad53e10', 'sao-luis-barreirinhas', 'São Luís', 'Barreirinhas', true, '≈ 4h', '260 km', 650, 900, 650, 950, 'Mais reservado', 100, 'O trajeto clássico do aeroporto de São Luís até a porta de entrada dos Lençóis Maranhenses.', 'Saída de qualquer ponto de São Luís — aeroporto, rodoviária, hotéis ou pousadas — direto até sua hospedagem em Barreirinhas. Viagem em carro particular com ar-condicionado, motorista da casa e paradas para água e banheiro no caminho. Atendemos voos de qualquer horário, inclusive madrugada, e acompanhamos o status do seu voo para ajustar o embarque sem custo extra.', ARRAY['Aeroporto Marechal Cunha Machado (São Luís)','Rodoviária de São Luís','Hotéis e pousadas em São Luís, Calhau, Ponta d''Areia e Centro Histórico','Hospedagens em Barreirinhas e beira do Rio Preguiças']::text[], '/frota/frota-1.jpeg', ARRAY['/frota/frota-1.jpeg','/frota/frota-2.jpeg','/frota/frota-3.jpeg','/frota/frota-4.jpeg']::text[], true, '2026-08-09T16:44:06.467072+00:00', '2026-08-09T16:44:06.467072+00:00'),
  ('a070f83a-bedf-4c81-a1ab-113e27f5ac4c', 'sao-luis-santo-amaro', 'São Luís', 'Santo Amaro', true, '≈ 4h30', '230 km', 700, 1050, NULL, NULL, 'Entrada tranquila dos Lençóis', 78, 'Acesso direto ao lado mais preservado do Parque Nacional, com menos movimento de turistas.', 'Transfer particular de São Luís até Santo Amaro do Maranhão, o acesso mais reservado do Parque Nacional dos Lençóis Maranhenses. Trecho final em estrada de areia feito com atenção e experiência: nossos motoristas fazem esse caminho todas as semanas. Embarque no aeroporto, na rodoviária ou na sua hospedagem em São Luís.', ARRAY['Aeroporto Marechal Cunha Machado (São Luís)','Hotéis e pousadas em São Luís','Pousadas em Santo Amaro do Maranhão']::text[], '/frota/frota-7.jpeg', ARRAY['/frota/frota-7.jpeg','/frota/frota-5.jpeg','/frota/frota-6.jpeg']::text[], true, '2026-08-09T16:44:06.467072+00:00', '2026-08-09T16:44:06.467072+00:00')
INSERT INTO public.conteudo_site (id, chave, secao, titulo, texto, imagem, ordem, created_at, updated_at) VALUES
  ('5488f7dd-5b0f-44c0-b1fc-a7422285fbe6', 'contato_intro', 'contato', 'Fale com a gente', 'Atendimento todos os dias pelo WhatsApp (98) 98150-6268.', '', 1, '2026-08-09T17:09:45.239783+00:00', '2026-08-09T17:09:45.239783+00:00'),
  ('0af26544-665f-460a-b586-abef03335170', 'frota_intro', 'frota', 'Nossa frota', 'Sedans e SUVs revisados, ar-condicionado, espaço para bagagem e cadeirinha sob solicitação.', '', 1, '2026-08-09T17:09:45.239783+00:00', '2026-08-09T17:09:45.239783+00:00'),
  ('fb876468-71b0-4451-b73f-05d5b92c028d', 'home_hero', 'home', 'Do desembarque às dunas', 'Transfer particular entre São Luís, Barreirinhas, Santo Amaro e toda a Rota das Emoções. Preço fechado por veículo, sem rateio e sem espera.', '', 1, '2026-08-09T17:09:45.239783+00:00', '2026-08-09T17:12:57.824743+00:00'),
  ('66df8aa4-dd8a-40e3-94d9-d86859a1736f', 'home_sobre', 'home', 'Rotas mais pedidas', 'Valores por veículo, já com combustível, pedágio e motorista.', '', 2, '2026-08-09T17:09:45.239783+00:00', '2026-08-09T17:12:41.180068+00:00')
